    @Transactional
    public Integer resolveQuestionField(Integer unitId, Integer fieldId, String fieldName) {
        if (fieldName == null || fieldName.isBlank()) {
            if (fieldId == null) throw new IllegalArgumentException("Vui lòng nhập hoặc chọn lĩnh vực.");
            return fieldId;
        }
        String name = fieldName.strip().replaceAll("\\s+", " ");
        if (name.length() > 100 || name.codePoints().anyMatch(Character::isISOControl))
            throw new IllegalArgumentException("Tên lĩnh vực tối đa 100 ký tự, không chứa ký tự điều khiển.");
        // Serialize creation per unit so concurrent submissions reuse the same field.
        DonVi unit = donViRepo.lockById(unitId)
                .orElseThrow(() -> new IllegalArgumentException("Không tìm thấy đơn vị yêu cầu."));
        if (!Boolean.TRUE.equals(unit.getHoatDong()))
            throw new IllegalArgumentException("Đơn vị đang tạm ngừng tiếp nhận.");
        var existing = linhVucRepo.findByDonVi_MaDonVi(unitId).stream()
                .filter(f -> f.getDonVi().getMaDonVi().equals(unitId) && f.getTenLinhVuc().equalsIgnoreCase(name))
                .findFirst();
        if (existing.isPresent()) {
            if (!"HoatDong".equals(existing.get().getTrangThai()))
                throw new IllegalArgumentException("Lĩnh vực này đang tạm ngừng. Vui lòng chọn lĩnh vực khác.");
            return existing.get().getMaLinhVuc();
        }
        return linhVucRepo.save(LinhVucTuVan.builder().donVi(unit).tenLinhVuc(name)
                .maLinhVucCode("SV_" + java.util.UUID.randomUUID().toString().replace("-", "").substring(0, 27))
                .moTa("Lĩnh vực được đề xuất khi đăng câu hỏi.").build()).getMaLinhVuc();
    }

    @Transactional
    public YeuCauTuVan createTicket(SinhVien sv, Integer maLinhVuc, Integer maDonVi, String tieuDe, String noiDung, Boolean baoMatDanhTinh) {
        if (tieuDe == null || tieuDe.trim().length() < 10) {
            throw new IllegalArgumentException("Tiêu đề yêu cầu tư vấn phải có tối thiểu 10 ký tự.");
        }
        if (noiDung == null || noiDung.trim().length() < 20) {
            throw new IllegalArgumentException("Nội dung chi tiết phải có tối thiểu 20 ký tự.");
        }
        DonVi donVi = donViRepo.findById(maDonVi).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy đơn vị yêu cầu."));
        LinhVucTuVan linhVuc = linhVucRepo.findById(maLinhVuc).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy lĩnh vực yêu cầu."));
        if (!Boolean.TRUE.equals(donVi.getHoatDong())) {
            throw new IllegalArgumentException("Đơn vị tư vấn đang tạm ngừng tiếp nhận yêu cầu.");
        }
        if (!linhVuc.getDonVi().getMaDonVi().equals(donVi.getMaDonVi()) || !"HoatDong".equals(linhVuc.getTrangThai())) {
            throw new IllegalArgumentException("Lĩnh vực tư vấn không thuộc đơn vị đã chọn hoặc đang tạm ngừng.");
        }
        LocalDateTime now = LocalDateTime.now(clock);
        LocalDateTime hanTiepNhan = slaService.calculateDeadline(now, 48);
        LocalDateTime hanSLA = slaService.calculateDeadline(now, 48);
        YeuCauTuVan ticket = YeuCauTuVan.builder().sinhVien(sv).donVi(donVi).linhVuc(linhVuc).tieuDe(tieuDe.trim()).noiDung(noiDung.trim()).baoMatDanhTinh(baoMatDanhTinh != null && baoMatDanhTinh).trangThai("ChoTiepNhan").ngayTao(now).ngayCapNhat(now).hanTiepNhan(hanTiepNhan).hanSLA(hanSLA).build();
        ticket = ticketRepo.saveAndFlush(ticket);
        forumService.publishNewTicket(ticket.getMaYeuCau());
        // Lưu lịch sử
        LichSuYeuCau ls = LichSuYeuCau.builder().yeuCauTuVan(ticket).taiKhoanThucHien(sv.getTaiKhoan()).hanhDong("TaoYeuCau").trangThaiMoi("ChoTiepNhan").ngayTao(now).build();
        lichSuRepo.save(ls);
        return ticket;
    }

    @Transactional
    public void claimTicket(Integer maYeuCau, NguoiTuVan cv) {
        YeuCauTuVan ticket = ticketRepo.findLockedById(maYeuCau).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy câu hỏi diễn đàn."));
        cv = nguoiTuVanRepo.findLockedById(cv.getMaCV()).orElseThrow();
        if (!"HoatDong".equals(cv.getTaiKhoan().getTrangThai())) throw new IllegalStateException("Tài khoản cố vấn chưa hoạt động.");
        long activeCount = ticketRepo.findByCoVanPhuTrach_MaCVOrderByNgayTaoDesc(cv.getMaCV()).stream().filter(t -> "DangXuLy".equals(t.getTrangThai())).count();
        if (activeCount >= cv.getHanNgachTiepNhan()) throw new IllegalStateException("Cố vấn đã đạt hạn ngạch tiếp nhận.");
        if (!"ChoTiepNhan".equals(ticket.getTrangThai())) {
            throw new IllegalStateException("Câu hỏi này đã được tiếp nhận hoặc xử lý bởi cố vấn khác.");
        }
        if (!ticket.getDonVi().getMaDonVi().equals(cv.getDonVi().getMaDonVi())) {
            throw new SecurityException("Bạn chỉ được tiếp nhận câu hỏi thuộc đơn vị của mình.");
        }
        if (!Boolean.TRUE.equals(cv.getNhanTuVan())) {
            throw new IllegalStateException("Tài khoản cố vấn hiện không ở trạng thái nhận tư vấn.");
        }
        LocalDateTime now = LocalDateTime.now(clock);
        ticket.setCoVanPhuTrach(cv);
        ticket.setTrangThai("DangXuLy");
        ticket.setNgayTiepNhan(now);
        ticket.setNgayCapNhat(now);
        ticketRepo.save(ticket);
        // Lưu phân công
        PhanCongTuVan pc = PhanCongTuVan.builder().yeuCauTuVan(ticket).taiKhoanThucHien(cv.getTaiKhoan()).coVanPhuTrach(cv).ngayPhanCong(now).ghiChu("Cố vấn chủ động nhận xử lý từ hàng đợi.").build();
        phanCongRepo.save(pc);
        // Lưu lịch sử
        LichSuYeuCau ls = LichSuYeuCau.builder().yeuCauTuVan(ticket).taiKhoanThucHien(cv.getTaiKhoan()).hanhDong("TiepNhan").trangThaiCu("ChoTiepNhan").trangThaiMoi("DangXuLy").ngayTao(now).build();
        lichSuRepo.save(ls);
        // Báo cho sinh viên
        notificationService.sendNotification(ticket.getSinhVien().getTaiKhoan(), "Câu hỏi diễn đàn đã được tiếp nhận", "Cố vấn " + cv.getTaiKhoan().getHoTen() + " đã tiếp nhận câu hỏi \'" + ticket.getTieuDe() + "\'.", "DienDan", "/student/tickets/" + ticket.getMaYeuCau());
        if (emailService != null && ticket.getSinhVien() != null && ticket.getSinhVien().getTaiKhoan() != null) {
            TaiKhoan svTk = ticket.getSinhVien().getTaiKhoan();
            if (svTk.getEmail() != null) {
                String sub = "[QAUTE] Câu hỏi của bạn đã được Cố vấn tiếp nhận: " + ticket.getTieuDe();
                String title = "Cố vấn đã tiếp nhận câu hỏi của bạn";
                String body = "Cố vấn <strong>" + cv.getTaiKhoan().getHoTen() + "</strong> (" + ticket.getDonVi().getTenDonVi() + ") đã tiếp nhận xử lý câu hỏi: <em>\"" + ticket.getTieuDe() + "\"</em>.<br>Cố vấn đang xem xét và sẽ sớm gửi phản hồi cho bạn.";
                emailService.sendAsyncNotification(svTk.getEmail(), sub, svTk.getHoTen(), title, body, "/student/tickets/" + ticket.getMaYeuCau(), "Xem chi tiết câu hỏi");
            }
        }
    }

    @Transactional
    public PhanHoiTuVan replyTicket(Integer maYeuCau, NguoiTuVan advisor, String noiDung, Boolean deXuatFaq) {
        if (noiDung == null || noiDung.trim().isEmpty()) {
            throw new IllegalArgumentException("Nội dung câu trả lời không được để trống.");
        }
        YeuCauTuVan ticket = ticketRepo.findLockedById(maYeuCau).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy câu hỏi diễn đàn."));
        requireAssignedAdvisor(ticket, advisor);
        if (!"DangXuLy".equals(ticket.getTrangThai())) {
            throw new IllegalStateException("Chỉ được phản hồi câu hỏi đang xử lý.");
        }
        TaiKhoan sender = advisor.getTaiKhoan();
        LocalDateTime now = LocalDateTime.now(clock);
        // Thêm phản hồi
        PhanHoiTuVan ph = PhanHoiTuVan.builder().yeuCauTuVan(ticket).taiKhoanGui(sender).loaiPhanHoi("TraLoi").noiDungTraLoi(noiDung.trim()).ngayTraLoi(now).deXuatFAQ(deXuatFaq != null && deXuatFaq).build();
        ph = phanHoiRepo.save(ph);
        // Cập nhật trạng thái ticket
        ticket.setTrangThai("DaPhanHoi");
        if (ticket.getNgayPhanHoiDau() == null) {
            ticket.setNgayPhanHoiDau(now);
        }
        ticket.setNgayPhanHoiCuoi(now);
        ticket.setHanTuDongDong(now.plusDays(7)); // 7 ngày tự động đóng nếu không hỏi thêm
        ticket.setNgayCapNhat(now);
        ticketRepo.save(ticket);
        // Lưu lịch sử
        LichSuYeuCau ls = LichSuYeuCau.builder().yeuCauTuVan(ticket).taiKhoanThucHien(sender).hanhDong("PhanHoi").trangThaiCu("DangXuLy").trangThaiMoi("DaPhanHoi").ngayTao(now).build();
        lichSuRepo.save(ls);
        // Nếu đề xuất FAQ
        if (deXuatFaq != null && deXuatFaq) {
            CauHoiFAQ faq = CauHoiFAQ.builder().cauHoi(ticket.getTieuDe()).cauTraLoi(noiDung.trim()).linhVuc(ticket.getLinhVuc()).yeuCauNguon(ticket).taiKhoanDeXuat(sender).trangThai("ChoDuyet").luotXem(0).ngayTao(now).build();
            faqRepo.save(faq);
        }
        // Báo cho sinh viên
        notificationService.sendNotification(ticket.getSinhVien().getTaiKhoan(), "Có câu trả lời cho yêu cầu tư vấn", "Câu hỏi \'" + ticket.getTieuDe() + "\' đã có phản hồi mới từ cố vấn.", "DienDan", "/student/tickets/" + ticket.getMaYeuCau());
        if (emailService != null && ticket.getSinhVien() != null && ticket.getSinhVien().getTaiKhoan() != null) {
            TaiKhoan svTk = ticket.getSinhVien().getTaiKhoan();
            if (svTk.getEmail() != null) {
                String sub = "[QAUTE] Cố vấn đã trả lời câu hỏi: " + ticket.getTieuDe();
                String title = "Câu hỏi của bạn đã có phản hồi mới từ Cố vấn";
                String preview = noiDung.length() > 300 ? noiDung.substring(0, 297) + "..." : noiDung;
                String body = "<strong>Cố vấn:</strong> " + advisor.getTaiKhoan().getHoTen() + "<br>"
                        + "<strong>Câu hỏi:</strong> " + ticket.getTieuDe() + "<br><br>"
                        + "<strong>Nội dung câu trả lời:</strong><br>" + preview.replace("\n", "<br>");
                emailService.sendAsyncNotification(svTk.getEmail(), sub, svTk.getHoTen(), title, body, "/student/tickets/" + ticket.getMaYeuCau(), "Xem chi tiết câu trả lời");
            }
        }
        return ph;
    }

    @Transactional
    public PhanHoiTuVan studentFollowUp(Integer maYeuCau, SinhVien student, String noiDung) {
        if (noiDung == null || noiDung.trim().isEmpty()) {
            throw new IllegalArgumentException("Nội dung câu hỏi thêm không được để trống.");
        }
        YeuCauTuVan ticket = ticketRepo.findLockedById(maYeuCau).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy câu hỏi diễn đàn."));
        requireTicketOwner(ticket, student);
        if (!"DaPhanHoi".equals(ticket.getTrangThai())) {
            throw new IllegalStateException("Chỉ được hỏi thêm sau khi cố vấn đã phản hồi.");
        }
        TaiKhoan sender = student.getTaiKhoan();
        LocalDateTime now = LocalDateTime.now(clock);
        PhanHoiTuVan ph = PhanHoiTuVan.builder().yeuCauTuVan(ticket).taiKhoanGui(sender).loaiPhanHoi("HoiThem").noiDungTraLoi(noiDung.trim()).ngayTraLoi(now).deXuatFAQ(false).build();
        ph = phanHoiRepo.save(ph);
        // Đổi lại trạng thái sang DangXuLy và hủy hạn tự đóng
        ticket.setTrangThai("DangXuLy");
        ticket.setHanTuDongDong(null);
        ticket.setNgayCapNhat(now);
        ticketRepo.save(ticket);
        LichSuYeuCau ls = LichSuYeuCau.builder().yeuCauTuVan(ticket).taiKhoanThucHien(sender).hanhDong("HoiThem").trangThaiCu("DaPhanHoi").trangThaiMoi("DangXuLy").ngayTao(now).build();
        lichSuRepo.save(ls);
        if (ticket.getCoVanPhuTrach() != null) {
            notificationService.sendNotification(ticket.getCoVanPhuTrach().getTaiKhoan(), "Sinh viên hỏi thêm", "Sinh viên bổ sung trao đổi trong câu hỏi: \'" + ticket.getTieuDe() + "\'.", "DienDan", "/advisor/tickets/" + ticket.getMaYeuCau());
            if (emailService != null && ticket.getCoVanPhuTrach().getTaiKhoan() != null) {
                TaiKhoan cvTk = ticket.getCoVanPhuTrach().getTaiKhoan();
                if (cvTk.getEmail() != null) {
                    String sub = "[QAUTE] Sinh viên gửi trao đổi bổ sung: " + ticket.getTieuDe();
                    String title = "Sinh viên bổ sung trao đổi trong câu hỏi";
                    String svName = Boolean.TRUE.equals(ticket.getBaoMatDanhTinh()) ? "Sinh viên ẩn danh" : student.getTaiKhoan().getHoTen();
                    String preview = noiDung.length() > 300 ? noiDung.substring(0, 297) + "..." : noiDung;
                    String body = "<strong>Sinh viên:</strong> " + svName + "<br>"
                            + "<strong>Câu hỏi:</strong> " + ticket.getTieuDe() + "<br><br>"
                            + "<strong>Nội dung trao đổi mới:</strong><br>" + preview.replace("\n", "<br>");
                    emailService.sendAsyncNotification(cvTk.getEmail(), sub, cvTk.getHoTen(), title, body, "/advisor/tickets/" + ticket.getMaYeuCau(), "Xem và trả lời câu hỏi");
                }
            }
        }
        return ph;
    }

    @Transactional
    public void closeTicket(Integer maYeuCau, SinhVien student, String ketLuan) {
        YeuCauTuVan ticket = ticketRepo.findLockedById(maYeuCau).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy câu hỏi diễn đàn."));
        requireTicketOwner(ticket, student);
        if (!"DaPhanHoi".equals(ticket.getTrangThai())) {
            throw new IllegalStateException("Chỉ có thể đóng câu hỏi đã có phản hồi.");
        }
        LocalDateTime now = LocalDateTime.now(clock);
        TaiKhoan sender = student.getTaiKhoan();
        ticket.setTrangThai("Dong");
        ticket.setNgayDong(now);
        ticket.setKetLuan(ketLuan != null ? ketLuan.trim() : "Đã hoàn tất tư vấn.");
        ticket.setNgayCapNhat(now);
        ticketRepo.save(ticket);
        LichSuYeuCau ls = LichSuYeuCau.builder().yeuCauTuVan(ticket).taiKhoanThucHien(sender).hanhDong("Dong").trangThaiCu("DaPhanHoi").trangThaiMoi("Dong").lyDo(ketLuan).ngayTao(now).build();
        lichSuRepo.save(ls);
    }

    @Transactional
    public void rateTicket(Integer maYeuCau, Integer maSV, Short soSao, String nhanXet) {
        if (soSao == null || soSao < 1 || soSao > 5) {
            throw new IllegalArgumentException("Điểm đánh giá phải từ 1 đến 5 sao.");
        }
        YeuCauTuVan ticket = ticketRepo.findLockedById(maYeuCau).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy câu hỏi diễn đàn."));
        if (!ticket.getSinhVien().getMaSV().equals(maSV)) {
            throw new IllegalArgumentException("Bạn chỉ có thể đánh giá câu hỏi diễn đàn của chính mình.");
        }
        if (!"DaPhanHoi".equals(ticket.getTrangThai()) && !"Dong".equals(ticket.getTrangThai())) {
            throw new IllegalStateException("Chỉ có thể đánh giá câu hỏi đã có phản hồi hoặc đã đóng.");
        }
        if (danhGiaRepo.existsByYeuCauTuVan_MaYeuCau(maYeuCau)) {
            throw new IllegalStateException("Câu hỏi diễn đàn này đã được đánh giá rồi (không thể sửa lại).");
        }
        DanhGiaYeuCau dg = DanhGiaYeuCau.builder().yeuCauTuVan(ticket).maSV(maSV).soSao(soSao).nhanXet(nhanXet != null ? nhanXet.trim() : "").ngayDanhGia(LocalDateTime.now(clock)).build();
        danhGiaRepo.save(dg);
    }

    @Transactional
    public void transferTicket(Integer maYeuCau, Integer maDonViMoi, Integer maLinhVucMoi, String lyDo, NguoiTuVan advisor) {
        YeuCauTuVan ticket = ticketRepo.findLockedById(maYeuCau).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy câu hỏi diễn đàn."));
        requireAssignedAdvisor(ticket, advisor);
        if (!"DangXuLy".equals(ticket.getTrangThai())) {
            throw new IllegalStateException("Chỉ được chuyển tiếp câu hỏi đang xử lý.");
        }
        if (lyDo == null || lyDo.trim().length() < 5) {
            throw new IllegalArgumentException("Lý do chuyển tiếp phải có ít nhất 5 ký tự.");
        }
        DonVi donViMoi = donViRepo.findById(maDonViMoi).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy đơn vị mới."));
        LinhVucTuVan linhVucMoi = linhVucRepo.findById(maLinhVucMoi).orElseThrow(() -> new IllegalArgumentException("Không tìm thấy lĩnh vực mới."));
        if (!linhVucMoi.getDonVi().getMaDonVi().equals(donViMoi.getMaDonVi()) || !"HoatDong".equals(linhVucMoi.getTrangThai())) {
            throw new IllegalArgumentException("Lĩnh vực mới không thuộc đơn vị mới hoặc đang tạm ngừng.");
        }
        TaiKhoan sender = advisor.getTaiKhoan();
        DonVi donViCu = ticket.getDonVi();
        LocalDateTime now = LocalDateTime.now(clock);
        // Kết thúc phân công cũ nếu có
        phanCongRepo.findByYeuCauTuVan_MaYeuCauAndNgayKetThucIsNull(maYeuCau).ifPresent(pc -> {
            pc.setNgayKetThuc(now);
            phanCongRepo.save(pc);
        });
        ticket.setDonVi(donViMoi);
        ticket.setLinhVuc(linhVucMoi);
        ticket.setCoVanPhuTrach(null);
        ticket.setTrangThai("ChoTiepNhan");
        ticket.setNgayCapNhat(now);
        ticketRepo.save(ticket);
        LichSuYeuCau ls = LichSuYeuCau.builder().yeuCauTuVan(ticket).taiKhoanThucHien(sender).hanhDong("ChuyenTiep").donViCu(donViCu).donViMoi(donViMoi).lyDo(lyDo).trangThaiMoi("ChoTiepNhan").ngayTao(now).build();
        lichSuRepo.save(ls);
    }

